-- Canonical trade IDs. The backend seed is the authoritative ID list for the existing trade catalog.
-- The frontend demo fixtures use these same IDs. Food Processing remains the explicit demo/catalog extension at ID 13.

do $$
begin
  if exists (select 1 from public.trades where id = 1 and name_en <> 'Electrician') then raise exception 'Trade id 1 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 2 and name_en <> 'Plumber') then raise exception 'Trade id 2 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 3 and name_en <> 'Welder') then raise exception 'Trade id 3 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 4 and name_en <> 'Fitter') then raise exception 'Trade id 4 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 5 and name_en <> 'Automobile Mechanic') then raise exception 'Trade id 5 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 6 and name_en <> 'Solar Technician') then raise exception 'Trade id 6 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 7 and name_en <> 'CNC Operator') then raise exception 'Trade id 7 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 8 and name_en <> 'Beautician & Wellness') then raise exception 'Trade id 8 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 9 and name_en <> 'Tailoring & Fashion') then raise exception 'Trade id 9 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 10 and name_en <> 'Data Entry & CSC Operator') then raise exception 'Trade id 10 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 11 and name_en <> 'HVAC & AC Technician') then raise exception 'Trade id 11 is already assigned to a different trade'; end if;
  if exists (select 1 from public.trades where id = 12 and name_en <> 'Mobile Phone Repair Tech') then raise exception 'Trade id 12 is already assigned to a different trade'; end if;
end $$;

insert into public.trades (id,name_en,name_local,sector,nsqf_level,duration_months,entry_qualification,safety_notes,job_roles,description_simple) values (2, 'Plumber', '{"hi": "प्लंबर", "te": "ప్లంబర్"}'::jsonb, 'Construction', 4, 12, 'Class 8 Pass', 'Gloves, safety footwear, eye shield', '["Pipe Fitter", "Sanitary Installer", "Plumbing Contractor"]'::jsonb, '{"en": "Fix water pipes, drains, and bathroom fittings", "hi": "पानी के पाइप, नालियां और सेनेटरी फिटिंग ठीक करना", "te": "నీటి పైపులు, డ్రైనేజీ మరియు బాత్‌రూమ్ అమరికలను బాగు చేయడం"}'::jsonb) on conflict (id) do nothing;
